import { useState } from "react";
import {
  CALORIE_INTENSITY_OPTIONS,
  WEIGHT_KG_MAX,
  WEIGHT_KG_MIN,
  parseWeightKg,
  type CalorieIntensityId,
} from "../../lib/ride/caloriesEstimate";
import "./RideSettingsSheet.css";

export type RideSettingsPanelProps = {
  rideTtsEnabled: boolean;
  onRideTtsEnabled: (enabled: boolean) => void;
  rideBgmEnabled: boolean;
  onRideBgmEnabled: (enabled: boolean) => void;
  rideCoachingBanner: boolean;
  onRideCoachingBanner: (enabled: boolean) => void;
  pacerEnabled: boolean;
  onPacerEnabled: (enabled: boolean) => void;
  rideBgmCatalogConfigured: boolean;
  rideElevationProfileLoading: boolean;
  /** 추정 kcal용 체중(kg). null = 미설정 */
  calorieWeightKg?: number | null;
  /** 저장 성공 여부. false 면 draft 를 prop 으로 되돌림 */
  onCalorieWeightKg?: (raw: string) => boolean | void;
  calorieIntensityId?: CalorieIntensityId | null;
  onCalorieIntensityId?: (id: CalorieIntensityId) => boolean | void;
  /** 계정 시트 등에 임베드 */
  embedded?: boolean;
};

/** TTS·BGM·코칭 배너 등 주행 설정 본문. 케이던스 센서는 HUD 센서 칩 → 센서 상세 설정이 소유한다. */
export function RideSettingsPanel(props: RideSettingsPanelProps) {
  const rootClass = props.embedded
    ? "ride-settings-panel ride-settings-panel--embedded"
    : "ride-settings-panel";
  const showCalorie =
    typeof props.onCalorieWeightKg === "function" &&
    typeof props.onCalorieIntensityId === "function";
  const [weightDraft, setWeightDraft] = useState(
    props.calorieWeightKg != null ? String(props.calorieWeightKg) : "",
  );
  // prop 체중 변경 시 draft 동기화 — effect setState 금지(react-hooks/set-state-in-effect)
  const [syncedWeightKg, setSyncedWeightKg] = useState(props.calorieWeightKg);
  if (props.calorieWeightKg !== syncedWeightKg) {
    setSyncedWeightKg(props.calorieWeightKg);
    setWeightDraft(props.calorieWeightKg != null ? String(props.calorieWeightKg) : "");
  }

  const revertWeightDraft = () => {
    setWeightDraft(props.calorieWeightKg != null ? String(props.calorieWeightKg) : "");
  };

  return (
    <div className={rootClass}>
      {showCalorie ? (
        <div className="ride-settings-sheet__group" aria-label="추정 칼로리">
          <span className="ride-settings-sheet__kicker">추정 kcal</span>
          <div className="ride-settings-sheet__calorie-row">
            <label className="ride-settings-sheet__weight" title="Body weight">
              <span>체중(kg)</span>
              <input
                type="number"
                inputMode="decimal"
                min={WEIGHT_KG_MIN}
                max={WEIGHT_KG_MAX}
                step={1}
                placeholder={`${WEIGHT_KG_MIN}–${WEIGHT_KG_MAX}`}
                value={weightDraft}
                onChange={(e) => {
                  const raw = e.target.value;
                  setWeightDraft(raw);
                  // 빈 칸·범위 밖은 확정 null. 입력 중(예: 7→70)은 draft만 유지.
                  if (raw.trim() === "") {
                    const ok = props.onCalorieWeightKg?.("");
                    if (ok === false) revertWeightDraft();
                    return;
                  }
                  if (parseWeightKg(raw) != null) {
                    const ok = props.onCalorieWeightKg?.(raw);
                    if (ok === false) revertWeightDraft();
                  }
                }}
                onBlur={() => {
                  const parsed = parseWeightKg(weightDraft);
                  if (parsed == null && weightDraft.trim() !== "") {
                    revertWeightDraft();
                  } else if (parsed != null) {
                    setWeightDraft(String(parsed));
                    const ok = props.onCalorieWeightKg?.(String(parsed));
                    if (ok === false) revertWeightDraft();
                  }
                }}
              />
            </label>
            <div className="ride-settings-sheet__chips" role="group" aria-label="강도">
              {CALORIE_INTENSITY_OPTIONS.map((opt) => {
                const active = props.calorieIntensityId === opt.id;
                return (
                  <button
                    key={opt.id}
                    type="button"
                    className={`ride-settings-sheet__chip${active ? " is-active" : ""}`}
                    aria-pressed={active}
                    title={opt.label}
                    onClick={() => {
                      props.onCalorieIntensityId?.(opt.id);
                    }}
                  >
                    {opt.label}
                  </button>
                );
              })}
            </div>
          </div>
          <p className="ride-settings-sheet__help">
            페달이 도는 시간과 선택 강도로 추정합니다. 체중·강도가 없으면 —. 센서 없으면
            측정 안 함. 주행 중 변경은 다음 주행부터.
          </p>
        </div>
      ) : null}

      <div className="ride-settings-sheet__group" aria-label="화면 표시">
        <span className="ride-settings-sheet__kicker">표시</span>
        <div className="ride-settings-sheet__toggles">
          <label className="ride-settings-sheet__toggle" title="Coaching banner">
            <input
              type="checkbox"
              checked={props.rideCoachingBanner}
              onChange={(e) => props.onRideCoachingBanner(e.target.checked)}
            />
            코칭 배너
          </label>
          <label className="ride-settings-sheet__toggle" title="Text-to-speech">
            <input
              type="checkbox"
              checked={props.rideTtsEnabled}
              onChange={(e) => props.onRideTtsEnabled(e.target.checked)}
            />
            TTS
          </label>
          <label
            className="ride-settings-sheet__toggle"
            title={!props.rideBgmCatalogConfigured ? "BGM not configured" : "Background music"}
          >
            <input
              type="checkbox"
              checked={props.rideBgmEnabled}
              disabled={!props.rideBgmCatalogConfigured}
              onChange={(e) => props.onRideBgmEnabled(e.target.checked)}
            />
            BGM
          </label>
          <label className="ride-settings-sheet__toggle" title="Pacer riders">
            <input
              type="checkbox"
              checked={props.pacerEnabled}
              onChange={(e) => props.onPacerEnabled(e.target.checked)}
            />
            페이서
          </label>
        </div>
        {props.rideElevationProfileLoading ? (
          <p className="ride-settings-sheet__help">고도 프로필 로드 중…</p>
        ) : null}
      </div>

    </div>
  );
}

.ride-settings-sheet {
  /* 메뉴 드로어(z-50) 위에 올라와야 함 — position:fixed 로 스테이지 밖에도 전체 덮음 */
  position: fixed;
  inset: 0;
  z-index: 56;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  pointer-events: none;
}

.ride-settings-sheet__scrim {
  position: absolute;
  inset: 0;
  background: rgba(2, 6, 23, 0.32);
  border: none;
  margin: 0;
  padding: 0;
  cursor: pointer;
  pointer-events: auto;
}

.ride-settings-sheet__panel {
  position: relative;
  z-index: 1;
  width: min(22rem, calc(100vw - 1rem));
  max-width: 100%;
  max-height: 65%;
  overflow: auto;
  margin-bottom: max(0.5rem, env(safe-area-inset-bottom, 0px));
  padding: 0.55rem 0.85rem 1rem;
  border-radius: 14px 14px 12px 12px;
  background: #FFFFFF;
  border: 1px solid #CBD5E1;
  color: #1F2937;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  animation: ride-settings-sheet-up 180ms ease-out;
  box-shadow: 0 -12px 36px rgba(0, 0, 0, 0.35);
}

@keyframes ride-settings-sheet-up {
  from {
    transform: translateY(16px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.ride-settings-sheet__handle {
  width: 2.4rem;
  height: 0.22rem;
  border-radius: 99px;
  background: #CBD5E1;
  align-self: center;
  margin-bottom: 0.15rem;
}

.ride-settings-sheet__title {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.ride-settings-sheet__group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.ride-settings-sheet__kicker {
  font-size: 0.62rem;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #64748B;
}

.ride-settings-sheet__toggles {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.65rem;
}

.ride-settings-sheet__toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.78rem;
  cursor: pointer;
}

.ride-settings-sheet__toggle input {
  accent-color: #2563EB;
}

.ride-settings-sheet__help {
  margin: 0;
  font-size: 0.68rem;
  color: #64748B;
  line-height: 1.35;
}

.ride-settings-sheet__device {
  margin: 0;
  font-size: 0.78rem;
}

.ride-settings-sheet__row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.ride-settings-sheet__btn {
  font: inherit;
  font-size: 0.76rem;
  font-weight: 650;
  padding: 0.4rem 0.75rem;
  border-radius: 8px;
  border: 1px solid #CBD5E1;
  background: #F1F5F9;
  color: #475569;
  cursor: pointer;
}

.ride-settings-sheet__btn:hover:not(:disabled) {
  background: #EFF6FF;
  border-color: #2563EB;
}

.ride-settings-sheet__btn--primary {
  background: #2563EB;
  border-color: #2563EB;
  color: #FFFFFF;
}

.ride-settings-sheet__btn--primary:hover:not(:disabled) {
  background: #1D4ED8;
  border-color: #1D4ED8;
}

.ride-settings-sheet__error {
  margin: 0;
  font-size: 0.68rem;
  color: #DC2626;
}

.ride-settings-sheet__calorie-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem 0.55rem;
}

.ride-settings-sheet__weight {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.76rem;
}

.ride-settings-sheet__weight input {
  width: 4.2rem;
  min-height: 44px;
  padding: 0.35rem 0.4rem;
  border-radius: 8px;
  border: 1px solid #CBD5E1;
  background: #FFFFFF;
  color: #1F2937;
  font: inherit;
  font-variant-numeric: tabular-nums;
}

.ride-settings-sheet__chips {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.ride-settings-sheet__chip {
  font: inherit;
  font-size: 0.76rem;
  font-weight: 650;
  min-height: 44px;
  padding: 0.35rem 0.55rem;
  border-radius: 8px;
  border: 1px solid #CBD5E1;
  background: #F1F5F9;
  color: #475569;
  cursor: pointer;
}

.ride-settings-sheet__chip:hover:not(:disabled) {
  background: #EFF6FF;
  border-color: #2563EB;
}

.ride-settings-sheet__chip.is-active {
  background: #2563EB;
  border-color: #2563EB;
  color: #FFFFFF;
}

.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-sheet__panel {
  width: min(32rem, calc(100vw - 1rem));
  max-height: calc(100vh - 1rem);
  max-height: calc(100dvh - 1rem);
  padding: 0.4rem 0.7rem 0.6rem;
  gap: 0.4rem;
}

.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-sheet__handle {
  display: none;
}

.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-panel {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-sheet__group {
  gap: 0.3rem;
}

/* Chief 2026-10-15: 주행 설정 한정 22px 입력/강도 예외. 프로필 22px와 같은 밀도. */
.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-sheet__panel {
  width: min(26rem, calc(100vw - 1rem));
  padding: 0.35rem 0.6rem 0.4rem;
  gap: 0.25rem;
}

.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-panel {
  gap: 0.3rem;
}

.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-sheet__group {
  gap: 0.15rem;
}

.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-sheet__weight input,
.ride-settings-sheet[aria-label="주행 설정"] .ride-settings-sheet__chip {
  box-sizing: border-box;
  height: 22px;
  min-height: 22px;
  padding-top: 0;
  padding-bottom: 0;
}

